from collections import Counter

class Solution:
    def numTilePossibilities(self, tiles: str) -> int:
        counts = Counter(tiles)

        def dfs() -> int:
            total = 0
            for ch in counts:
                if counts[ch] > 0:
                    total += 1
                    counts[ch] -= 1
                    total += dfs()
                    counts[ch] += 1
            return total

        return dfs()

class Solution {
public:
    int numTilePossibilities(string tiles) {
        vector<int> counts(26, 0);
        for (char c : tiles) counts[c - 'A']++;

        auto dfs = [&](auto& self) -> int {
            int total = 0;
            for (int i = 0; i < 26; ++i) {
                if (counts[i] > 0) {
                    total++;
                    counts[i]--;
                    total += self(self);
                    counts[i]++;
                }
            }
            return total;
        };

        return dfs(dfs);
    }
};

class Solution {
    public int numTilePossibilities(String tiles) {
        int[] counts = new int[26];
        for (char c : tiles.toCharArray()) counts[c - 'A']++;
        return dfs(counts);
    }

    private int dfs(int[] counts) {
        int total = 0;
        for (int i = 0; i < 26; ++i) {
            if (counts[i] > 0) {
                total++;
                counts[i]--;
                total += dfs(counts);
                counts[i]++;
            }
        }
        return total;
    }
}

var numTilePossibilities = function(tiles) {
    const counts = new Array(26).fill(0);
    for (const c of tiles) counts[c.charCodeAt(0) - 65]++;

    const dfs = () => {
        let total = 0;
        for (let i = 0; i < 26; i++) {
            if (counts[i] > 0) {
                total++;
                counts[i]--;
                total += dfs();
                counts[i]++;
            }
        }
        return total;
    };

    return dfs();
};
